$ErrorActionPreference = 'Stop'
$name = 'RelayToShop'
$prior = @(Get-OutboundConnector -Identity $name -ErrorAction Stop)
if ($prior.Count -ne 1 -or $prior[0].Name -ne $name) { throw 'Unexpected connector.' }
if (($prior[0].SmartHosts -join '|') -ne 'old-bridge.example.test') { throw 'Old value differs.' }
Set-OutboundConnector -Identity $name -SmartHosts 'bridge.example.test' -WhatIf -ErrorAction Stop

$ErrorActionPreference = 'Stop'
$read = Get-Command Get-TransportRule -ErrorAction Stop
if (-not $read.Parameters.ContainsKey('Identity')) { throw 'Identity is unavailable.' }
$rule = @(Get-TransportRule -Identity 'ReceiptMarker' -ErrorAction Stop)
if ($rule.Count -ne 1) { throw 'Expected one matching rule.' }
$rule | Select-Object Name,State,Mode,Comments | Export-Csv -LiteralPath ./rule-before.csv -NoTypeInformation -NoClobber

$ErrorActionPreference = 'Stop'
$edit = Get-Command Set-TransportRule -ErrorAction Stop
foreach ($key in 'Identity','Comments','WhatIf') {
    if (-not $edit.Parameters.ContainsKey($key)) { throw "Unavailable parameter: $key" }
}
Set-TransportRule -Identity 'ReceiptMarker' -Comments 'Practice review' -WhatIf -ErrorAction Stop
